// Read CALENDAR_IDS env (comma-separated). Emit one item per calendar.
// Plus compute the start / end ISO window for the lookahead period.

const idsEnv = $env.CALENDAR_IDS || '';
const ids = idsEnv.split(',').map(s => s.trim()).filter(Boolean);
if (ids.length === 0) {
  throw new Error('CALENDAR_IDS env var is empty.');
}

const lookaheadDays = Math.max(1, parseInt($env.CONFLICT_LOOKAHEAD_DAYS || '7', 10));
const now = new Date();
const end = new Date(now.getTime() + lookaheadDays * 24 * 60 * 60 * 1000);

return ids.map(id => ({
  json: {
    calendarId: id,
    timeMinIso: now.toISOString(),
    timeMaxIso: end.toISOString(),
  },
}));

// Per-calendar-ID sliding-window rate limit, opt-in.
// 60 fetches per hour per calendar.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return $input.all();
}

const LIMIT = 60;
const WINDOW_MS = 60 * 60 * 1000;
const MAX_KEYS = 200;

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 50);
  for (const [k] of oldest) delete buckets[k];
}

const out = [];
for (const item of $input.all()) {
  const id = item.json.calendarId;
  const hits = buckets[id] || [];
  if (hits.length >= LIMIT) continue;
  buckets[id] = [...hits, now];
  out.push(item);
}
return out;

// Pick provider from env. Default google.

const provider = ($env.CALENDAR_PROVIDER || 'google').toLowerCase();
return $input.all().map(item => ({ json: { ...item.json, provider } }));

// Normalize provider-specific event shapes into a stable schema.
// Google: items[].{id,summary,start,end,status,htmlLink}
// Outlook: value[].{id,subject,start,end,showAs,webLink}
//
// Microsoft Graph calendarView default returns dateTime in UTC with `timeZone: 'UTC'`.
// If the caller sets a `Prefer: outlook.timezone="..."` header (this template does not),
// the response can come back in a Windows timezone name like 'Eastern Standard Time'.
// In that case our normalization keeps the value as UTC (with a warning logged) because
// resolving Windows tz aliases requires a lookup table; false UTC interpretation is
// safer than V8 parsing the unsuffixed string as local server time.

const tzAlreadyEncoded = (s) => /(?:Z|[+-]\d{2}:?\d{2})$/.test(String(s || ''));

const toUtcIsoStrict = (dateTime, timeZone) => {
  if (!dateTime) return null;
  // If the string already carries an explicit offset suffix, parse as-is
  if (tzAlreadyEncoded(dateTime)) return new Date(dateTime).toISOString();
  // Otherwise this is the calendarView default shape: ISO without suffix in UTC
  if (timeZone && timeZone !== 'UTC') {
    console.log('[calendar] WARNING: Outlook event has timeZone=' + timeZone + ' but no offset suffix, treating as UTC');
  }
  return new Date(dateTime + 'Z').toISOString();
};

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const calendarId = (j.calendarId) || (j._calendarId) || ($('Set Provider').first() && $('Set Provider').first().json.calendarId) || 'unknown';
  const provider = j.provider || ($('Set Provider').first() && $('Set Provider').first().json.provider) || 'google';

  // Google envelope: { items: [...] }, Outlook envelope: { value: [...] }
  const eventArr = Array.isArray(j.items) ? j.items : (Array.isArray(j.value) ? j.value : []);

  for (const ev of eventArr) {
    let title = '';
    let startIso = null;
    let endIso = null;
    let url = null;
    let isAllDay = false;
    let included = true;

    if (provider === 'google') {
      if (String(ev.status || '') === 'cancelled') { included = false; }
      title = ev.summary || '(no title)';
      url = ev.htmlLink || null;
      const s = ev.start || {};
      const e = ev.end || {};
      isAllDay = !!s.date && !s.dateTime;
      // Google v3 events.list returns dateTime with offset suffix (`+02:00` or `Z`)
      startIso = s.dateTime ? new Date(s.dateTime).toISOString() : (s.date ? new Date(s.date + 'T00:00:00Z').toISOString() : null);
      endIso = e.dateTime ? new Date(e.dateTime).toISOString() : (e.date ? new Date(e.date + 'T23:59:59Z').toISOString() : null);
    } else {
      // outlook
      if (String(ev.showAs || '') === 'free') { included = false; }
      title = ev.subject || '(no subject)';
      url = ev.webLink || null;
      isAllDay = !!ev.isAllDay;
      const s = ev.start || {};
      const e = ev.end || {};
      startIso = toUtcIsoStrict(s.dateTime, s.timeZone);
      endIso = toUtcIsoStrict(e.dateTime, e.timeZone);
    }

    if (!included) continue;
    if (!startIso || !endIso) continue;

    out.push({ json: { calendarId, provider, eventId: ev.id || (calendarId + ':' + startIso), title, url, startIso, endIso, isAllDay } });
  }
}

return out;

// Detect overlapping events across DIFFERENT calendars.
// Pair-wise scan, only flag when calendarId differs and time ranges intersect.

const events = $input.all().map(i => i.json);
const byCal = {};
for (const e of events) {
  byCal[e.calendarId] = byCal[e.calendarId] || [];
  byCal[e.calendarId].push(e);
}

const toMs = iso => new Date(iso).getTime();
const conflicts = [];
const calIds = Object.keys(byCal);

for (let i = 0; i < calIds.length; i++) {
  for (let j = i + 1; j < calIds.length; j++) {
    const a = byCal[calIds[i]];
    const b = byCal[calIds[j]];
    for (const ea of a) {
      const aS = toMs(ea.startIso); const aE = toMs(ea.endIso);
      if (!Number.isFinite(aS) || !Number.isFinite(aE)) continue;
      for (const eb of b) {
        const bS = toMs(eb.startIso); const bE = toMs(eb.endIso);
        if (!Number.isFinite(bS) || !Number.isFinite(bE)) continue;
        const overlapStart = Math.max(aS, bS);
        const overlapEnd = Math.min(aE, bE);
        if (overlapStart < overlapEnd) {
          conflicts.push({
            json: {
              calendarA: ea.calendarId,
              calendarB: eb.calendarId,
              eventA: ea,
              eventB: eb,
              overlapStartIso: new Date(overlapStart).toISOString(),
              overlapEndIso: new Date(overlapEnd).toISOString(),
              overlapMinutes: Math.round((overlapEnd - overlapStart) / 60000),
            },
          });
        }
      }
    }
  }
}

return conflicts;

// 24-hour idempotency window on conflict-pair hash, opt-in.

const crypto = require('crypto');

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return $input.all();
}

const WINDOW_MS = 24 * 60 * 60 * 1000;
const MAX_KEYS = 20000;

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 2000);
  for (const [k] of oldest) delete seen[k];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const aId = j.eventA && j.eventA.eventId;
  const bId = j.eventB && j.eventB.eventId;
  if (!aId || !bId) { out.push(item); continue; }
  const sorted = [String(aId), String(bId)].sort().join(':');
  const dedupKey = crypto.createHash('sha256').update(sorted).digest('hex').slice(0, 32);
  if (seen[dedupKey]) continue;
  seen[dedupKey] = now;
  out.push(item);
}
return out;

// Redis variant for clustered n8n:
// const result = await redis.set('cf-idem:' + dedupKey, '1', 'EX', 86400, 'NX');
// if (result === null) continue;

// Fallback when a calendar fetch fails.

const input = $input.first();
const err = (input.json && input.json.error) || input.error || {};
const orig = input.json || {};

return [{
  json: {
    ok: false,
    fallback: true,
    calendarId: orig.calendarId || 'unknown',
    provider: orig.provider || 'unknown',
    error: {
      message: err.message || 'unknown error',
      name: err.name || 'CalendarFetchError',
    },
    receivedAt: new Date().toISOString(),
  },
}];
